"""
Independent log parser fixtures — hand-written representative log lines.

These fixtures are NOT generated by the parser code itself.
They are crafted to resemble real production log output from
common sources (application JSON logs, syslog-style text,
and Nginx access logs). Use these to validate parser behavior
without the false-pass risk of parser-generated test data.

Source/intent:
- JSON: mimics structured logging from a Node.js/Python app (pino/winston style)
- Text: mimics syslog and application console output
- Nginx: mimics standard combined log format from a reverse proxy
- Malformed: edge cases that should not crash parsing
"""

# ---------------------------------------------------------------------------
# JSON log fixtures (structured)
# ---------------------------------------------------------------------------

JSON_VALID_ENTRIES = [
    # Standard structured log with all expected fields
    '{"timestamp":"2024-03-15T10:23:45.123Z","level":"error","service":"auth-api","message":"Login failed for user_id=84729","requestId":"req-abc-123","duration_ms":42}',
    # Alternative field names (time, severity, logger) that parser should handle
    '{"time":"2024-03-15T11:00:00Z","severity":"WARN","logger":"payment-service","msg":"Retry webhook delivery attempt 3/5","retryCount":3,"targetUrl":"https://example.com/hooks/pay"}',
    # Minimal valid JSON log — only message, rest defaults
    '{"message":"Health check passed","status":"ok"}',
    # JSON with nested object in message
    '{"timestamp":"2024-03-15T12:30:00Z","level":"info","service":"scheduler","message":"Job batch_complete triggered","job":{"id":"job-991","type":"email-digest","count":1420}}',
    # Debug-level entry
    '{"timestamp":"2024-03-15T13:15:22Z","level":"debug","service":"db-pool","message":"Connection acquired from pool","poolSize":10,"active":3,"idle":7}',
]

JSON_MALFORMED_ENTRIES = [
    '',                                    # empty string
    'not json at all',                     # plain text, not JSON
    '{broken: json}',                      # unquoted keys
    '["array","not","object"]',           # JSON array, not dict
]


