# ---------------------------------------------------------------------------
# Nginx combined log format fixtures
# ---------------------------------------------------------------------------

NGINX_VALID_ENTRIES = [
    # Standard GET 200
    '192.168.1.100 - - [15/Mar/2024:14:23:10 +0000] "GET /api/users HTTP/1.1" 200 1234 "-" "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"',
    # POST 201 (created)
    '10.0.0.42 - admin [15/Mar/2024:14:25:33 +0000] "POST /api/orders HTTP/1.1" 201 567 "https://example.com/checkout" "Mozilla/5.0"',
    # 500 error (should map to level=error)
    '172.16.0.1 - - [15/Mar/2024:14:30:00 +0000] "GET /api/health HTTP/1.1" 500 23 "-" "curl/7.68.0"',
    # 404 (should map to level=warn)
    '192.168.1.50 - - [15/Mar/2024:14:35:22 +0000] "GET /old-page HTTP/1.1" 404 128 "-" "Googlebot/2.1"',
    # 301 redirect (warn)
    '10.0.0.1 - - [15/Mar/2024:14:40:00 +0000] "GET /blog/post HTTP/1.1" 301 0 "-" "Mozilla/5.0 (Macintosh)"',
    # With authenticated user
    '192.168.1.200 - john_doe [15/Mar/2024:14:45:55 +0000] "DELETE /api/sessions/current HTTP/1.1" 204 0 "https://app.example.com/settings" "Mozilla/5.0"',
]

NGINX_MALFORMED_ENTRIES = [
    '',                                    # empty
    'this is not an nginx log line at all',
    '192.168.1.1 - - [invalid-date] "GET / HTTP/1.1" 200 0 "-" "-"',  # bad date format (should not crash)
    'GARBAGE DATA $$$ %% @@',               # complete garbage (should not crash)
]
